	if (sceneLightsPlural === "few") return /** @type {LocalizedString} */ (`Непрерывное управление: ${i?.sceneLights} лампы в сцене, ${i?.zigbeeLights} лампы Zigbee; каждая лампа обновляется примерно раз в ${i?.interval}.`);
